function detailSelect(label,id,choices,value){return `<label>${label}<select id="${id}">${choices.map(c=>{let [v,t]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function detailToggle(label,key,value){return `<label class="checkrow"><input type="checkbox" data-detail-check="${key}" ${value?'checked':''}><span>${label}</span></label>`}
function detailText(label,id,value){return `<label>${label}<textarea id="${id}">${esc(value)}</textarea></label>`}
function detailError(){const d=detailsState();return `<div id="detail-error" role="alert" class="danger">${esc(d.error)}</div>`}
function detailFail(message,target){const d=detailsState();d.error=message;let el=$('#detail-error')||$('#form-error');if(el)el.textContent=message;else toast(message);if(target){const t=$('#'+target);t?.setAttribute('aria-invalid','true');t?.closest('details')?.setAttribute('open','');t?.focus()}return false}
function ipv4(s){const p=s.split('.');return p.length===4&&p.every(x=>/^(0|[1-9]\d{0,2})$/.test(x)&&Number(x)<=255)}
function ipv6(s){if(!/^[\da-f:.]+$/i.test(s)||s.includes(':::')||(s.match(/::/g)||[]).length>1)return false;let parts=s.split(':'),units=0;for(const x of parts.filter(Boolean)){if(x.includes('.')){if(!ipv4(x))return false;units+=2}else{if(!/^[\da-f]{1,4}$/i.test(x))return false;units++}}return s.includes('::')?units<8:units===8}
function asciiHost(s){return s.length<=253&&s.split('.').every(x=>/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(x))}
function detailEndpoint(raw,originOnly=false){if(!/^https?:\/\//i.test(raw)||/[\s\\?#@\u0000-\u001f\u007f]/.test(raw))return null;const m=raw.match(/^(https?):\/\/(\[[^\]]+\]|[^:/]+)(?::(\d+))?(\/.*)?$/i);if(!m)return null;const host=m[2].replace(/^\[|\]$/g,'').toLowerCase(),port=Number(m[3]||(m[1].toLowerCase()==='https'?443:80));if(port<1||port>65535)return null;if(host.includes(':')?!ipv6(host):/^\d+\.\d+\.\d+\.\d+$/.test(host)?!ipv4(host):!asciiHost(host))return null;if(originOnly&&m[4]&&m[4]!=='/')return null;let residence='PUBLIC_CLOUD';if(host==='localhost'||/^127\./.test(host)||host==='::1')residence='ON_DEVICE_LOOPBACK';else if(/^(10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host)||/^(fc|fd|fe[89ab])/i.test(host)&&host.includes(':')||/\.(local|localdomain|home\.arpa|lan|intranet|internal)$/.test(host)||!host.includes('.')&&!host.includes(':'))residence='USER_AUTHORIZED_LAN';else if(ipv4(host)||ipv6(host))residence='CUSTOM_REMOTE_UNKNOWN';return {origin:`${m[1].toLowerCase()}://${host.includes(':')?'['+host+']':host}:${port}`,host,port,path:m[4]||'',residence,http:m[1].toLowerCase()==='http'};}
function detailHeader(name,value){if(!name&&!value)return '';if(!name)return '有 Header 值时必须填写名称';if(!value)return 'Header 值不能为空';if(name.length>128||!/^[!#$%&'*+.^_`|~\da-z-]+$/i.test(name))return 'Header 名称不是合法 HTTP token（1–128 字符）';if(value.length>512||/[\u0000-\u001f\u007f]/.test(value))return 'Header 值最多 512 字符，禁止换行及控制字符';if(/auth|cookie|token|key|credential|password|secret/i.test(name)||/^proxy-/i.test(name)||['host','connection','upgrade','content-length','transfer-encoding','expect','te','trailer','x-helix-turn-id','x-helix-model-call-id'].includes(name.toLowerCase()))return '凭据、传输保留字段和追踪 Header 不可自配';return '';}
function detailProviderRead(){const p=detailsState().provider;for(const [id,key]of Object.entries({'provider-name':'name',protocol:'protocol',endpoint:'endpoint','model-id':'model','model-display':'display','header-name':'headerName','header-value':'headerValue'}))if($('#'+id))p[key]=read(id);return p;}
function detailProviderValid(discovery=false){const p=detailProviderRead();if(!p.name||p.name.length>128)return detailFail('来源名称需为 1–128 字符','provider-name');if(!detailEndpoint(p.endpoint))return detailFail('请输入合法 http/https Endpoint：禁止账号、查询、片段、IDN 和无效端口','endpoint');if(!discovery&&!p.editing&&(!p.model||p.model.length>256||/[\u0000-\u001f\u007f-\u009f]/.test(p.model)))return detailFail('精确模型 ID 需为 1–256 字符且不含控制字符','model-id');const err=detailHeader(p.headerName,p.headerValue);if(err)return detailFail(err,!p.headerName?'header-name':'header-value');if(p.template==='openrouter'&&p.headerName.toLowerCase()==='x-title')return detailFail('与模板 Header X-Title 冲突（名称不区分大小写）','header-name');if(p.display.length>256)return detailFail('模型显示名称最多 256 字符','model-display');detailsState().error='';return true;}
