function discoveryView(){const d=detailsState();if(d.discovery==='running')return '<div class="spinner"></div>'+btn('取消发现','detail-discover-cancel','outline');if(d.discovery==='error')return note('目录发现失败；来源未保存，原表单保留。','error')+btn('重试发现','detail-discover','outline');return '<p class="muted">模拟目录返回；并不证明生成能力。</p>'+d.catalog.map(x=>btn(esc(x),'detail-discover-pick:'+x,'listrow','model')).join('')+btn('模拟失败','detail-discover-error','outline');}
function hostsParse(text){const errors=[],map={};if(new TextEncoder().encode(text).length>131072)return {errors:['第 1 行：文档超过 128 KiB'],map};text.split(/\r?\n/).forEach((line,i)=>{const t=line.split('#')[0].trim();if(!t)return;const [ip,...names]=t.split(/\s+/);if(!names.length){errors.push(`第 ${i+1} 行：缺少主机名`);return}if(!(ipv4(ip)||ipv6(ip))){errors.push(`第 ${i+1} 行：无效 IP`);return}names.forEach(raw=>{let host=raw.toLowerCase().replace(/\.$/,'');try{if(/[^\x00-\x7f]/.test(host))host=new URL('https://'+host).hostname}catch{}if(!asciiHost(host)){errors.push(`第 ${i+1} 行：无效主机名`);return}map[host]||=[];if(!map[host].includes(ip))map[host].push(ip);if(map[host].length>16)errors.push(`第 ${i+1} 行：单主机超过 16 地址`)})});return {errors,map};}
function hostsFeedback(text){const p=hostsParse(text);return p.errors.length?p.errors.slice(0,20).map(e=>note(e,'error')).join(''):`<small>已解析 ${Object.keys(p.map).length} 个主机映射；注释、IPv4/IPv6、多别名与去重可演示。</small>`}
