function detailConfirm(a){const d=detailsState();if(!a)return false;if(a.startsWith('branch-')&&d.branchCandidate){d.branches.push(d.branchCandidate);d.branchCandidate=null;return false}if(a==='delete-file'){d.recovery||=[];const f=d.files.find(x=>x.path===d.file);d.recovery.push(structuredClone(f));d.files=d.files.filter(x=>x.path!==d.file);close(false);go('files');return true}if(a==='file-reload'){d.recovery||=[];d.recovery.push({path:d.file,body:S.fileText,type:'text',version:S.fileRevision});S.fileText=d.files.find(x=>x.path===d.file)?.body||'# 恢复版本';S.fileConflict=false;close();return true}if(a==='detail-defaults-reset'){S.saved.outputLimit='2048';S.saved.goalRounds='256';close();return true}if(a==='detail-quickjs-enable'){d.quickjsNative=true;close();return true}if(a==='detail-local-remove'){S.localLoaded=false;d.local.status='未安装';close();return true}if(a.startsWith('detail-reminder-delete:')){d.reminders.splice(Number(a.split(':')[1]),1);close();return true}if(a.startsWith('detail-storage:')){const kind=a.split(':')[1];d.storage[kind]=0;if(kind==='local'){S.localLoaded=false;d.local.status='未安装'}if(kind==='tts'){S.saved.ttsReady=false;S.tts=false}close();return true}if(a==='detail-schedule-retry'){d.lastAttempt='attempt-demo-'+((d.retryCount||0)+1);d.retryCount=(d.retryCount||0)+1;close();toast('已创建 '+d.lastAttempt+'（仅模拟）');return true}return false;}
