function detailInstallProgress(){const d=detailsState();later(()=>{if(d.local.status!=='下载中（模拟）')return;d.local.status='校验中（模拟）';if(modal?.type==='detail-local-progress')renderModal();later(()=>{if(d.local.status!=='校验中（模拟）')return;d.local.status='就绪（模拟）';if(modal?.type==='detail-local-progress')info('模型资产已就绪','<p>模拟校验完成；没有真实文件。需要再次主动加载。</p>');render()},500)},500)}
function detailInput(t){const d=detailsState();if(route==='provider'&&['provider-name','protocol','endpoint','model-id','model-display','header-name','header-value'].includes(t.id)){detailProviderRead();if(t.id==='endpoint'&&$('#endpoint-hint')){const e=detailEndpoint(t.value);$('#endpoint-hint').innerHTML=e?note((e.http?'HTTP 未加密 · ':'')+e.residence+' · '+esc(e.origin)):note('地址不合法，保存时拒绝','error')}}if(t.id==='hosts-text'){d.hosts=t.value;$('#hosts-feedback').innerHTML=hostsFeedback(t.value)}if(t.id==='command'&&d.terminals){const term=d.terminals.find(x=>x.id===(d.terminalId||1))||d.terminals[0];term.command=t.value;}if(t.id==='knowledge-prompt')d.knowledgePrompt=t.value;if(t.id==='user-answer')d.answerDraft=t.value;if(t.id==='collect-body')d.captureText=t.value;if(t.id==='collect-url')d.captureUrl=t.value;if(t.id==='mcp-json'){d.mcpDraft=t.value;d.mcpPreview=null}if(['context-window','context-ratio'].includes(t.id))detailContextRead();if(t.id?.startsWith('schedule-')){detailScheduleRead();d.scheduled.confirmed=false;const c=$('[data-detail-check="schedule-confirm"]');if(c)c.checked=false;}if(['speech-asr','speech-tts'].includes(t.id))detailSpeechRead();}
function detailChange(t){if(intentChange(t))return true;const d=detailsState();if(t.id==='provider-template'){detailProviderRead();const template=DETAIL_TEMPLATES.find(x=>x[0]===t.value);if(template){Object.assign(d.provider,{template:template[0],name:template[1],protocol:template[2],endpoint:template[3]});d.discovery=null;render()}return true}if(t.id==='protocol'){detailProviderRead();d.discovery=null;return true}if(t.id==='context-model'){detailContextRead();detailAction('detail-context:'+t.value);return true}if(t.id==='terminal-session'){d.terminalId=Number(t.value);render();return true}if(t.id==='question-choice-mode'){d.questionMode=t.value;if(t.value==='single'){const selected=S.selected.find(x=>x.startsWith('answer-'));S.selected=S.selected.filter(x=>!x.startsWith('answer-'));if(selected)S.selected.push(selected)}render();return true}if(t.dataset.check?.startsWith('answer-')&&d.questionMode==='single'){S.selected=S.selected.filter(x=>!x.startsWith('answer-'));if(t.checked)S.selected.push(t.dataset.check);render();return true}if(t.id==='history-size'){d.historySize=Number(t.value);d.historyPage=1;render();return true}if(t.id==='market-filter'){d.marketFilter=t.value;render();return true}if(!t.dataset.detailCheck)return false;const key=t.dataset.detailCheck,on=t.checked;if(key==='mobile-whole')d.mobileWhole=on;else if(key.startsWith('mobile-app:')){d.mobilePackages=(d.mobilePackages||[]).filter(x=>x!==key.slice(11));if(on)d.mobilePackages.push(key.slice(11))}else if(key.startsWith('tool-'))d.tools[key.slice(5)]=on;else if(key.startsWith('visible:')){const model=key.slice(8);d.visible=d.visible.filter(x=>x!==model);if(on)d.visible.push(model)}else if(key==='reminder-timed')d.reminderDraft.timed=on;else if(key==='reminder-exact')d.reminderDraft.exact=on;else if(key==='context-auto'){detailContextRead();d.context.automatic=on;renderModal()}else if(key==='context-compact')d.context.compact=on;else if(key==='speech-ws'){detailSpeechRead();d.speech.ws=on;d.speech.account=on||d.speech.account;d.speech.asr=on?'wss://asr.example.invalid/ws/asr':'https://asr.example.invalid/v1/audio/transcriptions';d.speech.tts=on?'wss://tts.example.invalid/ws/tts':'https://tts.example.invalid/v1/audio/speech';renderModal()}else if(key==='speech-enabled')d.speech.enabled=on;else if(key==='speech-account'){if(d.speech.ws&&!on){t.checked=true;toast('固定流式服务必须使用账号登录')}else d.speech.account=on}else if(key==='quickjs-native')d.quickjsCandidate=on;else if(key.startsWith('file-select:')){const path=key.slice(12);d.fileSelection=d.fileSelection.filter(x=>x!==path);if(on)d.fileSelection.push(path)}else if(key.startsWith('source-')){const mapped=key==='source-one'?'source-1':'source-2';S.selected=S.selected.filter(x=>x!==mapped);if(on)S.selected.push(mapped)}else if(key==='market-confirm')d.marketConfirmed=on;else if(key==='connector-search')d.connectorSearch=on;else if(key==='connector-read')d.connectorRead=on;else if(key.startsWith('schedule-')){if(key==='schedule-confirm')d.scheduled.confirmed=on;else if(key==='schedule-enabled')d.scheduled.enabled=on;else{const tool=key.slice(9);d.scheduled.tools=d.scheduled.tools.filter(x=>x!==tool);if(on)d.scheduled.tools.push(tool);d.scheduled.confirmed=false;const c=$('[data-detail-check="schedule-confirm"]');if(c)c.checked=false}}else if(key.startsWith('report-'))d.reportInclude[key.slice(7)]=on;else if(key.startsWith('cleanup:')){d.cleanup=(d.cleanup||[]).filter(x=>x!==key.slice(8));if(on)d.cleanup.push(key.slice(8))}else if(key.startsWith('message-reference:')){const i=Number(key.slice(18));d.messageReferences=(d.messageReferences||[]).filter(x=>x!==i);if(on)d.messageReferences.push(i)}return true;}

function detailBeforeClose(){const d=detailsState();if(modal?.type==='detail-models'&&d.modelsBefore){d.catalog=[...d.modelsBefore.catalog];d.visible=[...d.modelsBefore.visible];d.displayNames={...d.modelsBefore.names};d.modelsBefore=null}if(modal?.type==='detail-rules'&&d.ruleBefore){d.ruleSource=d.ruleBefore.source;d.rules={...d.ruleBefore.rules};d.ruleBefore=null}if(modal?.type==='detail-speech'&&d.speechBefore){d.speech=structuredClone(d.speechBefore);d.speechBefore=null}if(modal?.type==='detail-schedule'&&d.scheduleBefore){d.scheduled=structuredClone(d.scheduleBefore);d.scheduleBefore=null}if(modal?.type==='detail-local-progress'&&['下载中（模拟）','校验中（模拟）'].includes(d.local.status))d.local.status='已取消 · 未安装'}

function detailFinish(){const d=detailsState(),parent=d.modalParent;d.modalParent=null;close(false);if(parent)open(parent);else render()}

function detailScenario(id){switch(id){case 'voice-timeout':S.draft='原来的文字';S.voicePermission=true;go('chat');inlineVoiceStart();S.voiceText='达到 120 秒后的最终识别文本（模拟）';inlineVoiceFinish();return true;case 'voice-focus-loss':S.draft='焦点丢失前的草稿';S.voicePermission=true;go('chat');S.voice='idle';info('录音已停止（焦点丢失模拟）','<p>音频焦点丢失，停止本次录音，原草稿保留，不自动恢复。</p>');return true;case 'source-failure':detailsState().sourceStates.one='提取失败';detailsState().sourceId='one';go('source');return true;case 'catalog-signature':detailsState().marketTrusted=false;go('market');return true;case 'context-save-failure':go('provider');detailAction('detail-context:demo-model');detailAction('detail-context-save-error');return true;case 'system-picker':go('collect');open('detail-picker',{purpose:'capture'});return true;case 'restart-review':S.tool='UNKNOWN · 重启后原调用需核对';S.goal='阻塞 · 未知副作用';go('goal');open('tool');return true;default:return false}}

function detailContextKey(model){const d=detailsState(),e=detailEndpoint(d.provider.endpoint);return (d.contextLocal?'on-device:demo-asset':e?e.origin+e.path:d.provider.endpoint)+'|'+model}

/* Product-intent refinements: organization, authority and build/profile are distinct. */
function intentState(){const d=detailsState();d.buildChannel||='Standard';d.sessionDirectory||='/workspace/mobile';d.memberships||={current:'mobile',research:'mobile',reading:'reading'};d.projectInstructions||={mobile:'先核对资料与权限边界；把已验证事实和建议分开。',reading:'整理要点并保留引用。'};d.projectMemory||={};return d;}
function intentPage(){const d=intentState();let out;switch(route){
case 'question':{const sources=S.selected.filter(x=>x==='source-1'||x==='source-2');out=intro('基于资料提问','先明确范围，再决定把哪些片段发给模型。')+card('本次上下文',`<div class="row">${sources.map(id=>'<span class="pill">'+(id==='source-1'?'离线语音权限说明':'Android 音频焦点')+'</span>').join('')||'<p>尚未选定来源</p>'}</div><p class="muted">处理模型：${esc(S.model)}；只有所选片段与问题会进入本次模拟请求。</p>`+btn('调整所选来源','question-sources','outline','book'))+field('你的问题','knowledge-prompt',d.knowledgePrompt||'这些资料对取消和权限有什么共同要求？')+btn('核对范围并提问','question-generate','primary','send').replace('<button ', '<button '+(!sources.length?'disabled ':''))+(S.knowledgeSaved?card('回答',`<p>录音需要明确开始，取消保持原草稿。${d.snapshots.map((_,i)=>'['+(i+1)+']').join('')}</p>`+btn('核对引用片段','citation','outline')+btn('保存为可编辑笔记','answer-save','primary')):'')+(!sources.length?note('请先选择来源。这里不会悄悄使用整个知识库。'):'');break;}
case 'extensions':out=intro('插件','查看已添加能力，按需配置并选择用于会话。',btn('添加','intent-plugin-add','primary','plus'))+`<div class="tabs">${link('extensions','已添加','puzzle')}${link('market','发现','search')}</div>`+search('extensions')+(S.installed?card('资料助手',`<span class="pill">外部插件 · ${S.connected?'已连接':'待配置'}</span><div class="row">${btn('配置','connector-config','outline')}${btn('提示与工具','intent-plugin-content:user','outline')}${btn('详情','intent-plugin-detail:user','outline')}</div>`):'')+card('浏览器',`<span class="pill">内置 · 随 APK 更新</span><div class="row">${btn('配置','intent-plugin-detail:browser','outline')}${btn('提示与工具','intent-plugin-content:browser','outline')}${btn('详情','intent-plugin-detail:browser','outline')}</div>`)+card('独立技能',link('skill','资料整理','book','独立安装归属，卸载其他插件不移除本技能'))+btn('选择当前会话能力','session-capabilities','outline','puzzle');break;
case 'plugin':{const bundled=d.pluginTarget==='browser';out=intro(bundled?'浏览器 · 内置插件':'资料助手','配置完整、会话选中与操作授权分别检查。')+card('配置',bundled?'<p>无需额外账号配置；网站访问和本地操作仍正常授权。</p>':link('connectors','连接器与登录配置','puzzle'))+card('会话使用',detailToggle('默认用于新会话（不改变已有会话）','plugin-default',!!d.pluginDefault)+btn('选择用于当前会话','session-capabilities','outline'))+card('提示与工具',btn('查看只读贡献内容','intent-plugin-content','outline','book'))+card('来源与维护',`<p>${bundled?'APK 内置贡献；代码随应用更新。':'本地演示安装 · 版本 '+(d.pluginVersion||'1.0')+' · 外部插件'}</p>`+(bundled?btn('检查配置 / 修复','readiness-open','outline'):btn('查看更新说明','intent-plugin-update','outline')+btn('卸载此插件','plugin-uninstall','danger')));break;}
case 'projects':{const rows=d.projects.filter(p=>matches(p.name)&&(S.filter==='archived'?p.archived:!p.archived));out=intro('项目','组织长期工作，不复制会话权限或自动搬动文件。',btn('新建项目','create-project','primary','plus'))+tabs([['all','进行中'],['archived','已归档']],S.filter)+search('projects')+rows.map(p=>btn(`<span class="grow"><strong>${esc(p.name)}</strong><small>${Object.values(d.memberships).filter(id=>id===p.id).length} 个会话 · ${esc(p.directory)}</small></span>›`,'detail-project-open:'+p.id,'listrow','folder')).join('')+(!rows.length?empty('此分类没有项目'):'');break;}
case 'project':{const p=d.projects.find(x=>x.id===d.projectId);if(!p){out=empty('项目已移除，原会话与文件保留');break}const tab=d.projectTab||'conversations';out=intro(p.name,p.archived?'已归档 · 内容与运行保留':'项目说明、指令、主目录和会话归属分别管理。',btn('项目设置','edit-project','outline','settings'))+`<div class="tabs">${[['conversations','会话'],['files','文件'],['tasks','任务'],['artifacts','成果'],['context','指令与记忆']].map(([id,t])=>btn(t,'intent-project-tab:'+id,tab===id?'selected':'')).join('')}</div>`;
if(tab==='conversations')out+=card('项目会话',Object.entries(d.memberships).filter(([,id])=>id===p.id).map(([id])=>`<div class="row"><button class="grow listrow" data-action="intent-project-conversation:${id}">${icon('chat')}${esc(({current:'当前会话',research:'Android 权限研究',reading:'周末阅读清单'})[id])}</button>${btn('移出 / 转移','intent-membership:'+id,'outline')}</div>`).join('')+btn('在项目中新建会话','project-chat','primary','plus')+btn('加入现有会话','intent-membership:current','outline'))+note('加入/移出/转移只改组织归属，不搬文件、不更改原会话目录。');
if(tab==='files')out+=card('项目主目录',`<p>${esc(p.directory)}</p><small>真实目录入口；成果不是影子文件目录。</small>`+btn('打开项目文件','intent-project-files','primary','folder'));
if(tab==='tasks')out+=card('项目任务',p.id==='mobile'?link('goal','完善语音接入方案','work',S.goal+' · 保留原会话身份'):empty('该项目暂无任务'));
if(tab==='artifacts')out+=card('项目成果',p.id==='mobile'?link('artifact','语音接入方案.md','file','来源：当前会话 / 原 Turn'):empty('该项目暂无成果'));
if(tab==='context')out+=detailText('共享指令（不提供权限）','project-instructions',d.projectInstructions[p.id]||'')+detailToggle('启用项目记忆','project-memory',!!d.projectMemory[p.id]?.enabled)+detailToggle('允许自动写入项目记忆','project-memory-auto',!!d.projectMemory[p.id]?.automatic)+detailText('项目记忆正文','project-memory-body',d.projectMemory[p.id]?.body||'')+btn('保存指令与记忆','intent-project-context-save','primary')+note('按稳定项目 ID 隔离；默认不自动开启记忆，不自动注入其他会话历史。');
out+=`<div class="row" style="margin-top:24px">${btn(p.archived?'恢复项目':'归档项目','intent-project-archive','outline','folder')}${btn('删除项目元数据','intent-project-delete','danger','trash')}</div>`;break;}
case 'speech':out=intro('语音输入与回复朗读','离线输入开箱可用；云端需明确配置与内容去向。')+card('语音输入',`<span class="pill">${d.speech.enabled?(d.speech.ws?'云端流式':'云端整段识别'):'本机离线流式识别'}</span><p>主动录音 → 输入框实时识别 → 结束后原处编辑 → 主动发送。</p>`+btn('配置云端 ASR / TTS','cloud-speech','outline','settings'))+card('回复朗读',`<span class="pill">${S.saved.ttsReady?'本地资源就绪':'本地资源未准备'}</span><p>正文朗读与云端输入分别配置；支持明确停止，不提供伪暂停。</p>`+btn('管理本地资源','tts-resources','outline','download')+btn('系统语音状态','system-voice','outline','sound'))+note('录音、回复朗读不同时占用音频资源。离开聊天、后台或焦点丢失后停止，不自动恢复。');break;
case 'question-input':out=intro('需要你补充信息','回答绑定原问题；取消不伪造结果。')+card('优先处理哪个方向？',check('权限边界','answer-permission',S.selected.includes('answer-permission'))+check('语音体验','answer-voice',S.selected.includes('answer-voice'))+field('补充说明（最多 4000 字符）','user-answer',d.answerDraft||'')+`<small>${d.questionMode==='single'?'本次为单选':'本次允许多选'}；也可填写自己的答案。</small>`+detailError()+btn('提交答案','question-submit','primary')+btn('取消回答','question-cancel','outline'));break;
case 'terminal':case 'mobile':case 'proot':if(d.buildChannel==='Standard')out=intro(PAGES.find(x=>x.id===route).title,'此开发者能力不属于当前 Standard 构建可用表面。')+note('你可以继续使用完整会话、自配模型、知识库、提醒与本地语音。评审 Advanced 布局请在画布外切换构建渠道。')+link('capabilities','查看实际能力条件','model');break;
}
return out===undefined?null:out;}
function intentModal(){const d=intentState();if(modal?.type==='intent-membership'){const session=modal.session;return sheet('会话的项目归属',detailSelect('目标项目','membership-target',[['none','不属于项目'],...d.projects.filter(p=>!p.archived).map(p=>[p.id,p.name])],d.memberships[session]||'none')+note('不搬文件、不复制权限、不修改该会话原目录。活动 Turn 或待发送输入期间禁止迁移。')+detailError(),btn('取消','close')+btn('保存组织归属','intent-membership-save','primary'))}if(modal?.type==='profile')return sheet('安全 profile',`<p>发行渠道：${d.buildChannel}；当前 profile：${S.saved.channel||'Standard'}</p>`+note('发行渠道来自安装的构建；profile 是该构建允许的安全策略，不能在设置里把 Standard 安装变成 Advanced。')+(d.buildChannel==='Advanced'?btn('Standard profile','profile-standard','listrow','shield')+btn('Advanced profile · 需确认','intent-profile-request','listrow warn','shield'):'<p>Standard 构建只提供 Standard profile。</p>'),btn('关闭','close'));return null;}
function intentAction(action){const d=intentState(),[a,...rest]=action.split(':'),v=rest.join(':');switch(a){
case 'branch':if(S.messages[Number(v)]?.role!=='assistant'){toast('只有模型回复提供创建分支');return true}return false;
case 'edit-message':if(S.messages[Number(v)]?.role!=='user'){toast('只允许编辑用户消息');return true}if(S.stream){toast('先停止生成再编辑消息');return true}return false;
case 'voice':if(S.voice==='recording'){inlineVoiceFinish();return true}if(!S.voicePermission){open('microphone');return true}inlineVoiceStart();return true;
case 'microphone-allow':S.voicePermission=true;close(false);inlineVoiceStart();return true;
case 'microphone-deny':S.voicePermission=false;close(false);S.voice='idle';d.voiceError='麦克风权限被拒绝；仍可文字输入，点击麦克风可重新申请。';render();return true;
case 'voice-finish':inlineVoiceFinish();return true;
case 'voice-cancel':inlineVoiceCancel();close(false);render();return true;
case 'inline-voice-dismiss':d.voiceError='';render();return true;
case 'send':if(S.voice==='recording'){toast('先结束录音，再编辑或发送');return true}return false;
case 'intent-plugin-add':info('添加插件或技能',link('market','发现可安装内容','search')+btn('导入插件包','detail-package-picker','listrow','folder')+btn('导入独立技能','detail-skill-import','listrow','book')+btn('创作技能','skill-create','listrow','edit')+`<details><summary>高级接入</summary>${btn('粘贴 MCP JSON','detail-mcp-import','listrow','terminal')}</details>`);return true;
case 'intent-plugin-detail':d.pluginTarget=v;go('plugin');return true;
case 'intent-plugin-content':if(v)d.pluginTarget=v;info('提示与工具 · 只读检查',d.pluginTarget==='browser'?'<p>内置网页任务技能：在用户选定网页范围内导航、观察与交互。</p><p>工具来自当前 APK 的浏览器贡献；网页输出不授予本地权限。</p>':'<p>资料整理技能：核对来源，输出引用与待办。</p><p>工具：documents.search / documents.read（演示）。声明不是许可。</p><small>配置在连接器页；工具禁用在权限页；本页不提供第二套授权。</small>');return true;
case 'readiness-open':go('readiness');return true;
case 'intent-plugin-update':info('资料助手更新','<p>1.0 → 1.1</p><p>作者说明：改进资料检索提示。贡献变化：更新整理技能；端点与认证范围不变。</p>'+note('点击更新即表达对当前展示版本的安装意图；不另加重复批准工具的弹窗。')+btn('更新到 1.1（模拟）','intent-plugin-update-commit','primary'));return true;
case 'intent-plugin-update-commit':if(!d.marketTrusted)return detailFail('目录签名未验证，原版本保留'),true;d.pluginVersion='1.1';close();toast('模拟更新完成，原会话选择保留，不批准后续工具');return true;
case 'intent-workbench':intentWorkbenchFocus=document.activeElement;d.workbench=v||'artifact';intentWorkbench();if(intentIsPhone())$('#workbench button')?.focus();return true;
case 'intent-workbench-close':d.workbench=null;intentWorkbench();if(intentWorkbenchFocus?.isConnected)intentWorkbenchFocus.focus();return true;
case 'artifact-reference':if(d.workbench){d.workbench=null;intentWorkbench()}return false;
case 'answer-save':d.answerNoteId||='answer-note-demo-1';S.noteText='录音需要明确开始，取消保持原草稿。'+d.snapshots.map((_,i)=>'['+(i+1)+']').join('');go('note');toast('保存为可编辑笔记；未核对为事实，重复保存使用同一身份');return true;
case 'settings-hub':info('设置',link('settings','通用设置','settings')+link('defaults','Agent 默认行为','model')+link('permissions','权限与安全','shield')+link('runtime','运行环境','terminal')+link('storage','存储管理','folder')+link('audit','诊断与审计','tool'));return true;
case 'profile-advanced':if(d.buildChannel!=='Advanced')return toast('当前构建不支持 Advanced profile'),true;return false;
case 'intent-profile-request':confirm('启用 Advanced profile','<p>只改变安全 profile。仍需能力、数据边界和具体调用授权，不能扩大 Plan 职责。</p>','intent-profile');return true;
case 'detail-egress-create':if(d.buildChannel!=='Advanced')return detailFail('当前 Standard 构建不支持 Advanced 持久高敏感出站规则'),true;return false;
case 'plugin-uninstall':if(d.pluginTarget==='browser')return toast('内置代码随 APK 更新，不可独立卸载'),true;confirm('卸载资料助手','<p>只移除本插件拥有的贡献和连接。独立安装或其他插件引用的技能保留，用户资料保留；在途调用按原身份结算。</p>','intent-plugin-uninstall');return true;
case 'intent-project-tab':d.projectTab=v;render();return true;
case 'detail-project-open':d.projectTab='conversations';return false;
case 'intent-membership':open('intent-membership',{session:v});return true;
case 'intent-membership-save':if(S.stream||d.pendingInput)return detailFail('会话正在执行或有待发送输入，不能迁移归属'),true;{const target=read('membership-target');if(target==='none')delete d.memberships[modal.session];else d.memberships[modal.session]=target;close();toast('仅更新项目归属；目录和权限保持原值');return true}
case 'intent-project-conversation':go('chat');return true;
case 'project-chat':{const p=d.projects.find(x=>x.id===d.projectId);freshChat();d.memberships.current=p.id;d.sessionDirectory=p.directory;S.permission=d.permissionDefault;toast('新会话使用项目主目录与新会话权限默认，不复制旧会话权限');return true}
case 'intent-project-files':d.cwd='';go('files');toast('项目主目录：'+d.projects.find(x=>x.id===d.projectId).directory+'（示例文件视图）');return true;
case 'intent-project-context-save':{if(read('project-instructions').length>16000)return detailFail('共享指令最多 16000 字符'),true;const id=d.projectId;d.projectInstructions[id]=read('project-instructions');d.projectMemory[id]||={enabled:false,automatic:false};d.projectMemory[id].body=read('project-memory-body');toast('按项目 ID 保存；不授予工具权限或注入其他会话历史');return true}
case 'intent-project-archive':{const p=d.projects.find(x=>x.id===d.projectId);p.archived=!p.archived;render();toast(p.archived?'已归档，不停止任务、不删除内容':'已恢复项目');return true}
case 'intent-project-delete':if(S.stream||d.pendingInput)return toast('项目有未完成执行/输入，不能移除上下文归属'),true;confirm('删除项目元数据','<p>仅删除项目和成员关系。保留所有会话、目录、文件及项目记忆；同名新项目获得新身份。</p>','intent-project-delete');return true;
case 'confirm-do':if(modal?.confirmAction==='intent-plugin-uninstall'){S.installed=false;S.pluginEnabled=false;d.independentSkillRetained=true;close();toast('插件已移除；独立技能与用户内容保留');return true}if(modal?.confirmAction==='intent-profile'){S.saved.channel='Advanced';close();return true}if(modal?.confirmAction==='intent-project-delete'){if(S.stream||d.pendingInput)return detailFail('执行状态已变化，删除未提交'),true;const id=d.projectId;d.projects=d.projects.filter(p=>p.id!==id);for(const key of Object.keys(d.memberships))if(d.memberships[key]===id)delete d.memberships[key];close(false);go('projects');toast('元数据已移除，会话/文件/目录与记忆保留');return true}return false;
case 'goal-resume':if(S.goal.startsWith('正在推进'))return toast('当前目标正在运行，无需创建另一个 Run'),true;return false;
case 'speech-save':return toast('请通过云端语音配置保存实际来源，未改变当前设置'),true;
}return false;}
function intentChange(t){const d=intentState();if(t.dataset.detailCheck==='plugin-default'){d.pluginDefault=t.checked;return true}if(t.id==='review-build'){d.buildChannel=t.value;if(t.value==='Standard')S.saved.channel='Standard';render();return true}if(t.id==='question-choice-mode'){d.questionMode=t.value;if(t.value==='single'){const answer=S.selected.find(x=>x.startsWith('answer-'));S.selected=S.selected.filter(x=>!x.startsWith('answer-'));if(answer)S.selected.push(answer)}render();return true}if(t.dataset.detailCheck==='project-memory'||t.dataset.detailCheck==='project-memory-auto'){d.projectMemory[d.projectId]||={enabled:false,automatic:false,body:''};d.projectMemory[d.projectId][t.dataset.detailCheck==='project-memory'?'enabled':'automatic']=t.checked;return true}return false;}
function intentNav(){const d=intentState();intentNavigationSelection();if(d.buildChannel==='Standard')$('#nav [data-route="terminal"]')?.remove();const settings=$('#nav [data-route="settings"]');if(settings){settings.removeAttribute('data-route');settings.dataset.action='settings-hub';settings.classList.toggle('active',['settings','defaults','permissions','system','runtime','storage','audit','speech','network','about'].includes(route));}const label=$('#channel-label');if(label)label.textContent=d.buildChannel+' · profile '+(S.saved.channel||'Standard');}

function intentNavigationSelection(){const parent={project:'projects',provider:'models',subscription:'models',local:'models',plugin:'extensions',market:'extensions',connectors:'extensions',skills:'extensions',skill:'extensions',source:'knowledge',note:'knowledge',question:'knowledge',collect:'knowledge',reminder:'reminders',goal:'tasks',plan:'tasks',background:'tasks',artifact:'artifacts',file:'files',location:'files',session:'chat',search:'chat'}[route];if(parent){const b=$('#nav [data-route="'+parent+'"]');if(b){b.classList.add('active');b.setAttribute('aria-current','location')}}}

function intentReviewSync(){const values={'review-build':intentState().buildChannel,'account-control':S.account,'state-control':S.state,'question-choice-mode':detailsState().questionMode||'multiple'};for(const [id,value]of Object.entries(values)){const select=$('#'+id);if(!select)continue;const options=[...select.querySelectorAll('option')];options.forEach(o=>o.selected=false);const option=options.find(o=>(o.getAttribute('value')||o.textContent)===value);if(option)option.selected=true}}

function intentWorkbench(){const panel=$('#workbench');if(!panel)return;const d=intentState();panel.hidden=route!=='chat'||!d.workbench;const phone=intentIsPhone(),mask=$('#workbench-mask');if(mask)mask.hidden=panel.hidden||!phone;for(const el of [$('.main'),$('#nav')]){if(!panel.hidden&&phone)el?.setAttribute('inert','');else el?.removeAttribute('inert')}if(!panel.hidden&&phone){panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true')}else{panel.removeAttribute('role');panel.removeAttribute('aria-modal')}if(panel.hidden){panel.innerHTML='';return}panel.innerHTML=`<div class="row between"><h2>语音接入方案</h2>${btn('关闭侧览','intent-workbench-close','','close')}</div><small>当前会话成果 · 纯模拟预览</small><div class="card soft"><h3>建议流程</h3><ol><li>主动开始录音</li><li>识别文字实时进入输入框</li><li>结束后原处编辑，再主动发送</li></ol><p>取消不改变原稿，云端处理先说明内容去向。</p></div><p class="muted">已生成示例内容；发布成果不代表源文件回写。执行、核验和模型读取仍需分别确认。</p>${btn('引用到当前草稿','artifact-reference','primary','book')}${link('artifact','打开完整成果','file')}`;}

let intentWorkbenchFocus=null;
function intentIsPhone(){return !!($('#app')?.classList.contains('phone')||window.matchMedia?.('(max-width:760px)').matches)}
document.addEventListener('click',event=>{if(event.target.id==='workbench-mask')handle('intent-workbench-close')});
document.addEventListener('keydown',event=>{const panel=$('#workbench');if(!panel||panel.hidden||!intentIsPhone()||modal)return;if(event.key==='Escape'){event.preventDefault();handle('intent-workbench-close')}if(event.key==='Tab'){const controls=[...panel.querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
window.addEventListener('resize',()=>{if(typeof S!=='undefined'&&S)intentWorkbench()});

/* Owner-requested design revision: dictate directly into the composer. */
function inlineVoiceStart(){const d=intentState();if(S.stream){toast('请先停止生成，再开始录音');return}S.tts=false;d.voiceBase=S.draft;d.voiceGeneration=(d.voiceGeneration||0)+1;const generation=d.voiceGeneration;d.voiceError='';S.voice='recording';S.voiceText='帮我整理这份接入方案，重点检查权限边界。';render();later(()=>{if(S.voice!=='recording'||generation!==d.voiceGeneration)return;inlineVoicePartial('帮我整理这份接入方案');later(()=>{if(S.voice==='recording'&&generation===d.voiceGeneration)inlineVoicePartial(S.voiceText)},700)},400)}
function inlineVoicePartial(text){const d=intentState();if(S.voice!=='recording')return;d.voicePartial=text;S.draft=(d.voiceBase||'')+(d.voiceBase?'\n':'')+text;const input=$('#draft');if(input)input.value=S.draft;}
function inlineVoiceFinish(){const d=intentState();if(S.voice!=='recording')return;inlineVoicePartial(S.voiceText);d.voiceGeneration++;S.voice='idle';d.voiceBase=null;d.voiceError='';render();$('#draft')?.focus();toast('识别文字已留在输入框，可直接编辑；未发送')}
function inlineVoiceCancel(reason='已取消录音，恢复原草稿'){const d=intentState();if(S.voice==='recording'||S.voice==='loading'){S.draft=d.voiceBase??S.draft;d.voiceGeneration=(d.voiceGeneration||0)+1;d.voiceBase=null;S.voice='idle';d.voicePartial='';}d.voiceError=reason;}
function inlineVoiceControls(){const d=intentState();if(S.voice==='recording')return `<div class="voice-inline" role="status"><span class="voice-dot" aria-hidden="true"></span><span class="grow">录音中 · 识别文字实时进入输入框<small>结束后可直接编辑，最多 120 秒</small></span>${btn('取消','voice-cancel')}${btn('结束录音','voice-finish','primary','check')}</div>`;return d.voiceError?`<div class="voice-inline"><span class="grow muted" role="status">${esc(d.voiceError)}</span>${btn('关闭提示','inline-voice-dismiss')}</div>`:'';}
